import zipfile

# Symbolic constants to replace magic strings
ZIP_MODE_READ = 'r'
ZIP_MODE_WRITE = 'w'


class ZipFileProcessor:
    def __init__(self, file_name):
        self._file_name = file_name

    def _open_zip_for_reading(self):
        """
        Opens the zip file for reading.
        Returns a ZipFile object or None if an error occurs.
        """
        try:
            return zipfile.ZipFile(self._file_name, ZIP_MODE_READ)
        except (IOError, OSError, zipfile.BadZipFile):
            return None

    def read_zip_file(self):
        return self._open_zip_for_reading()

    def _safely_extract(self, extract_action, output_path, member_name=None):
        """
        Helper to safely perform extraction operations.
        Separate Query from Modifier? No, this is a helper.
        Extract Method: Consolidated duplicate logic.
        """
        try:
            with zipfile.ZipFile(self._file_name, ZIP_MODE_READ) as zip_file:
                if extract_action == 'all':
                    zip_file.extractall(output_path)
                elif member_name is not None:
                    zip_file.extract(member_name, output_path)
                else:
                    return False
            return True
        except (IOError, OSError, zipfile.BadZipFile):
            return False

    def extract_all(self, output_path):
        return self._safely_extract('all', output_path)

    def extract_file(self, file_name, output_path):
        return self._safely_extract('single', output_path, file_name)

    def create_zip_file(self, files, output_file_name):
        try:
            with zipfile.ZipFile(output_file_name, ZIP_MODE_WRITE) as zip_file:
                for file in files:
                    zip_file.write(file)
            return True
        except (IOError, OSError, zipfile.BadZipFile):
            return False

    @property
    def file_name(self):
        return self._file_name

    @file_name.setter
    def file_name(self, value):
        self._file_name = value
